// Meitou's own player-facing texts (docs/formats/localisation.md "Meitou's own texts"): finds them in the code, keeps
// src/Meitou.Core/Localisation/locale/meitou.pot in step with it, and checks every built-in <code>.po holds a translation of each.
//
//   node .github/scripts/loc-strings.mjs           check: the template matches the code and no catalog misses a message (exit 1 if not)
//   node .github/scripts/loc-strings.mjs --write   rewrite meitou.pot from the code
//   node .github/scripts/loc-strings.mjs --json    the check's findings as JSON (for loc-fill.mjs)
//
// A text is a message when it is an argument of a translating call anywhere (Loc.Tr, Loc.TrIn, Loc.Plural, LauncherText.Translate,
// UpperTr), or prose in a player-facing file (SCOPE), or a caption in a launcher .axaml file. Prose found that the player never reads
// as Meitou's text (a widget type, a record name, a string Kenshi's own catalog translates) is listed in meitou.ignore.
import { readFileSync, writeFileSync, readdirSync, statSync, existsSync, appendFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parsePo, writePot } from './po.mjs';

const root = fileURLToPath(new URL('../../', import.meta.url));
const localeDir = join(root, 'src/Meitou.Core/Localisation/locale');
const potPath = join(localeDir, 'meitou.pot');
const ignorePath = join(localeDir, 'meitou.ignore');
const builtPath = join(localeDir, 'meitou.built');

/** Folders and files whose prose the player reads (repository-relative, '/' separators). */
const SCOPE = [
  /^src\/Meitou\.Game\/(Settings|Title|Ui|Building|Tutorials|Mods|Host\/Photo)\//,
  /^src\/Meitou\.Game\/(SettingsMenu|PlayerInterface)[^/]*\.cs$/,
  /^launcher\/Meitou\.Launcher\//,
  // Setting labels, hints and choices defined beside the renderer and the content they control.
  /^src\/Meitou\.Game\/Rendering\/(Frame\/(Enhancements|WorldFrame)|Post\/(PostProcessOptions|Upscaling)|Upscalers\/FrameGenerationSetup)\.cs$/,
  /^src\/Meitou\.(Core\/Content\/CoveredMods|Data\/Textures\/TextureQuality)\.cs$/,
];

/**
 * Calls that translate their arguments, matched in code with literals blanked: the name is in one of the groups. Every literal of the first
 * argument (two for TrIn and Plural) is a message, so a ternary or a ?? of literals is found as well as a plain one. Mark is gettext's N_: a
 * table entry that a later Tr of the variable translates. Tr alone is the launcher's wrapper of LauncherText.Translate.
 */
const CALLS = /(?:\bLoc\.(Tr|TrIn|Plural|Mark|TrCaption)|\bLauncherText\.(Translate)|(?<![\w.])(UpperTr|UpperCaption|Tr))\s*\(/g;

/** Lines whose literals are never shown: logs, exceptions, assertions, resource names, layout and widget properties. */
const NOT_SHOWN = new RegExp([
  String.raw`Console\.`, String.raw`\bthrow\b`, String.raw`Exception\(`, String.raw`\bDebug\.`, String.raw`\bTrace\.`,
  String.raw`\bAssert`, String.raw`nameof\(`, String.raw`\bRegex`, String.raw`GetManifest`, String.raw`DllImport`,
  String.raw`\bcon\.`, String.raw`usage:`, String.raw`BeginGuest|BeginNative`, String.raw`\.Get[A-Z]\w*\("`,
  String.raw`\bFind\(`, String.raw`StartsWith|EndsWith`, String.raw`\bType ==|\bName ==`, String.raw`Diagnostic`,
  String.raw`\["(TextAlign|FontName|ImageTexture|ImageName|Skin|Align|Colour)"\]`, String.raw`\bcase\b`,
].join('|'));

/** The axaml attributes that hold captions (the launcher translates them when it shows the window). */
const AXAML_ATTRIBUTES = /\s(Text|Content|ToolTip\.Tip|Watermark|PlaceholderText|Header|Title)="([^"{][^"]*)"/g;

const mode = process.argv[2] ?? '--check';
const found = collect();
const ignored = readIgnore(ignorePath);
const messages = [...found.messages.values()].filter((m) => !isIgnored(m));
const POT_NOTE = 'Meitou\'s own texts; generated by .github/scripts/loc-strings.mjs --write, do not edit.';
/** The header of meitou.built. */
const BUILT_HEADER = '# Texts the code builds with $"..." (or hands to Loc.Tr built) in player-facing places, which no catalog can match. The check\n'
  + '# fails on any built text not listed here: give new text to Loc.Tr with {1}, {2} placeholders instead. --write only removes lines.\n';


if (mode === '--write') write();
else report(check());

/** Writes meitou.pot from the code, and drops from meitou.built the texts the code no longer builds (it never adds one). */
function write() {
  writeFileSync(potPath, writePot(messages, POT_NOTE));
  const built = new Set([...found.built.values()].map((b) => b.id));
  const kept = [...readList(builtPath)].filter((id) => built.has(id)).sort();
  writeFileSync(builtPath, BUILT_HEADER + kept.map((id) => id.replaceAll('\n', '\\n')).join('\n') + '\n');
  console.log(`meitou.pot: ${messages.length} messages; meitou.built: ${kept.length} texts left to convert.`);
}

/**
 * Whether a message without a context is on the ignore list: a game text only where the launcher does not show it (it reads no game catalog,
 * so a text it hands to Tr or shows as an axaml caption needs Meitou's own entry even when Kenshi translates the same words).
 */
function isIgnored(m) {
  if (m.context !== null) return false;
  return ignored.notShown.has(m.id) || (ignored.game.has(m.id) && !m.launcher);
}

/** The findings: whether meitou.pot is stale, built texts not in the baseline, and per catalog what it lacks or gets wrong. */
function check() {
  const stale = !existsSync(potPath) || readFileSync(potPath, 'utf8') !== writePot(messages, POT_NOTE);
  const baseline = readList(builtPath);
  const built = [...found.built.values()].filter((b) => !baseline.has(b.id));
  const catalogs = readdirSync(localeDir).filter((f) => f.endsWith('.po')).sort().map((f) => audit(f));
  return { stale, built, catalogs };
}

/**
 * What <file> (a built-in catalog) gets wrong: missing lists each message without a usable translation (with the reason when an entry exists
 * but cannot be used), duplicates the messages entered twice, orphans the entries of no message.
 */
function audit(file) {
  const text = readFileSync(join(localeDir, file), 'utf8');
  const nplurals = Number(text.match(/nplurals\s*=\s*(\d+)/)?.[1] ?? 2);
  const entries = parsePo(text);
  const byKey = new Map();
  const duplicates = [];
  for (const e of entries) {
    const k = key(e.msgctxt, e.msgid);
    if (byKey.has(k)) duplicates.push(e.msgid);
    byKey.set(k, e);
  }

  const missing = [];
  for (const m of messages) {
    const e = byKey.get(key(m.context, m.id));
    const reason = e ? problem(m, e, nplurals) : 'no entry';
    if (reason) missing.push({ ...m, reason });
  }

  const wanted = new Set(messages.map((m) => key(m.context, m.id)));
  const orphans = entries.filter((e) => !wanted.has(key(e.msgctxt, e.msgid))).length;
  return { code: file.slice(0, -'.po'.length), nplurals, missing, duplicates, orphans };
}

/** Why entry <e> cannot translate message <m> (the runtime skips fuzzy entries and shows an empty form as nothing), or null when it can. */
function problem(m, e, nplurals) {
  if (e.comments.some((c) => /^#,.*\bfuzzy\b/.test(c))) return 'fuzzy';
  if (m.plural && !e.msgidPlural) return 'singular entry for a plural message';
  if (!m.plural && e.msgidPlural) return 'plural entry for a singular message';

  const forms = m.plural ? e.msgstr : e.msgstr.slice(0, 1);
  if (forms.length !== (m.plural ? nplurals : 1) || forms.some((f) => !f)) return m.plural ? `needs ${nplurals} non-empty forms` : 'empty';

  const allowed = new Set([...placeholders(m.id), ...placeholders(m.plural ?? '')]);
  for (const f of forms) {
    const used = placeholders(f);
    if (used.some((p) => !allowed.has(p))) return `placeholder ${used.find((p) => !allowed.has(p))} is not in the English`;
    if (!m.plural && used.length !== allowed.size) return 'drops a placeholder';
    if (edges(f) !== edges(m.id)) return 'leading or trailing space or line break differs';
  }
  return null;
}

/** The distinct {N...} placeholders of <text>, sorted. */
function placeholders(text) {
  return [...new Set(text.match(/\{\d+[^{}]*\}/g) ?? [])].sort();
}

/** Whether <text> starts and ends with a space or line break, as a short code. */
function edges(text) {
  return `${/^[ \n]/.test(text)}${/[ \n]$/.test(text)}`;
}

/** Prints the findings (and a GitHub step summary); exits 1 when the template is stale, a built text is new, or a catalog falls short. */
function report(findings) {
  if (mode === '--json') {
    console.log(JSON.stringify(findings, null, 2));
    return;
  }

  const lines = [];
  if (findings.stale) lines.push('meitou.pot does not match the code: run `node .github/scripts/loc-strings.mjs --write`.');
  for (const c of findings.catalogs) reportCatalog(c, lines);
  if (findings.built.length) {
    lines.push(`${findings.built.length} new texts are built with $"..." where a player reads them, so no catalog can match them; give them to`
      + ' Loc.Tr with {1}, {2} placeholders:');
    for (const b of findings.built.slice(0, 50)) lines.push(`  - ${JSON.stringify(b.id)} (${b.refs[0]})`);
  }

  const failed = findings.stale || findings.built.length > 0 || findings.catalogs.some((c) => c.missing.length || c.duplicates.length);
  if (!failed) lines.unshift(`Translations complete: ${messages.length} messages in ${findings.catalogs.length} catalogs.`);
  console.log(lines.join('\n'));
  if (process.env.GITHUB_STEP_SUMMARY) appendFileSync(process.env.GITHUB_STEP_SUMMARY, '```\n' + lines.join('\n') + '\n```\n');
  process.exitCode = failed ? 1 : 0;
}

/** Adds one catalog's shortfalls to <lines>. */
function reportCatalog(c, lines) {
  if (c.missing.length) {
    lines.push(`${c.code}.po lacks a usable translation of ${c.missing.length} of ${messages.length} messages:`);
    for (const m of c.missing.slice(0, 50)) lines.push(`  - ${JSON.stringify(m.id)} (${m.reason}; ${m.refs[0]})`);
    if (c.missing.length > 50) lines.push(`  ... and ${c.missing.length - 50} more`);
  }
  if (c.duplicates.length) lines.push(`${c.code}.po enters ${c.duplicates.length} messages twice: ${c.duplicates.slice(0, 10).map((d) => JSON.stringify(d)).join(', ')}`);
}

/** Every message found in the code (by context and id), and the built prose that cannot be one. */
function collect() {
  const result = { messages: new Map(), built: new Map() };
  for (const file of sourceFiles()) {
    const text = readFileSync(join(root, file), 'utf8');
    if (file.endsWith('.axaml')) collectAxaml(file, text, result);
    else collectCSharp(file, text, result);
  }
  return result;
}

/** The repository-relative .cs files under src/ and launcher/ and the launcher's .axaml files, sorted. */
function sourceFiles() {
  const files = [];
  const walk = (dir) => {
    for (const name of readdirSync(join(root, dir))) {
      const path = `${dir}/${name}`;
      if (name === 'bin' || name === 'obj') continue;
      if (statSync(join(root, path)).isDirectory()) walk(path);
      else if (name.endsWith('.cs') || (name.endsWith('.axaml') && dir.startsWith('launcher'))) files.push(path);
    }
  };
  walk('src');
  walk('launcher');
  return files.sort();
}

/** Adds the captions of an axaml file. */
function collectAxaml(file, text, result) {
  for (const match of text.matchAll(AXAML_ATTRIBUTES)) {
    const id = unescapeXml(match[2]);
    if (isProse(id)) add(result.messages, null, id, null, file, true);
  }
}

/** Adds the messages of a C# file: every literal argument of a translating call anywhere, prose literals in player-facing files. */
function collectCSharp(file, text, result) {
  const { lits, masked } = scan(text);
  const used = new Set();
  for (const call of calls(masked)) addCall(call, lits, file, result, used, masked);
  if (!SCOPE.some((s) => s.test(file))) return;

  const lines = text.split('\n');
  for (const lit of lits) {
    if (used.has(lit.start)) continue;
    const line = lines[lit.line - 1];
    const code = line.replace(lit.raw, ' '.repeat(lit.raw.length));
    if (NOT_SHOWN.test(code) || isDictionaryKey(line, lit.raw) || !isProse(lit.value)) continue;
    if (lit.interpolated) add(result.built, null, lit.value, null, file);
    else add(result.messages, null, lit.value, null, file);
  }
}

/** The translating calls of masked code: { name, args: [[from, to], ...] } with each argument's span. */
function calls(masked) {
  const out = [];
  for (const m of masked.matchAll(CALLS)) {
    const name = m[1] ?? m[2] ?? m[3];
    out.push({ name, args: argumentSpans(masked, m.index + m[0].length) });
  }
  return out;
}

/** The spans of the arguments of a call whose parenthesis opens just before <i> in masked code (top-level commas split them). */
function argumentSpans(masked, i) {
  const spans = [];
  let depth = 0;
  let from = i;
  for (let j = i; j < masked.length; j++) {
    const ch = masked[j];
    if (ch === '(' || ch === '[' || ch === '{') depth++;
    else if ((ch === ')' || ch === ']' || ch === '}') && depth > 0) depth--;
    else if (ch === ',' && depth === 0) {
      spans.push([from, j]);
      from = j + 1;
    } else if (ch === ')' && depth === 0) {
      spans.push([from, j]);
      return spans;
    }
  }
  spans.push([from, masked.length]);
  return spans;
}

/** Adds the messages of one call: TrIn's first-argument literal as the context of its second's, Plural's first and second as pairs. */
function addCall(call, lits, file, result, used, masked) {
  const inArg = (n) => (call.args[n] ? lits.filter((l) => l.start >= call.args[n][0] && l.end <= call.args[n][1] && isValue(l, call.args[n][0], masked)) : []);
  const first = inArg(0);
  for (const l of first) used.add(l.start);
  if (call.name === 'TrIn' || call.name === 'Plural') {
    const second = inArg(1);
    for (const l of second) used.add(l.start);
    if (call.name === 'TrIn') for (const l of second) addMessage(result, first[0]?.value ?? null, l, null, file);
    else second.forEach((l, k) => addMessage(result, null, first[k] ?? first[0], l.value, file));
    return;
  }
  for (const l of first) addMessage(result, null, l, null, file);
}

/**
 * Whether literal <lit> in an argument starting at <from> is a value the argument can be, not a key: an indexer's key, a switch arm's pattern,
 * a comparison's operand or another method's argument (props.GetValueOrDefault("Caption")) is not.
 */
function isValue(lit, from, masked) {
  const pattern = /^\s*=>/.test(masked.slice(lit.end, lit.end + 8));
  const operand = /[=!]=\s*$/.test(masked.slice(Math.max(0, lit.start - 8), lit.start));
  if (lit.indexer || pattern || operand) return false;
  let depth = 0;
  for (let j = lit.start - 1; j >= from; j--) {
    const ch = masked[j];
    if (ch === ')' || ch === ']' || ch === '}') depth++;
    else if (ch === '(' || ch === '[' || ch === '{') {
      if (depth === 0) return !(ch === '(' && /[\w>]\s*$/.test(masked.slice(Math.max(0, j - 40), j)));
      depth--;
    }
  }
  return true;
}

/** Adds literal <lit> as a message (or as built text when interpolated); a literal without words has nothing to translate. */
function addMessage(result, context, lit, plural, file) {
  if (!lit || !hasWords(lit.value)) return;
  if (lit.interpolated) add(result.built, null, lit.value, null, file);
  else add(result.messages, context, lit.value, plural, file, true);
}

/** Records a message (or built text) with the file it is in; <translated> when a call or caption translates it there (not a prose guess). */
function add(map, context, id, plural, file, translated = false) {
  const k = key(context, id);
  const entry = map.get(k) ?? { context, id, plural, refs: [], launcher: false };
  if (plural && !entry.plural) entry.plural = plural;
  if (translated && file.startsWith('launcher/')) entry.launcher = true;
  if (!entry.refs.includes(file)) entry.refs.push(file);
  map.set(k, entry);
}

/** The map key of a message: its context and id. */
function key(context, id) {
  return `${context ?? ''}\u0004${id}`;
}

/** A list file: one text per line ('\n' for a line break), '#' lines and blank lines skipped; empty when the file is absent. */
function readList(path) {
  if (!existsSync(path)) return new Set();
  return new Set(readFileSync(path, 'utf8').split('\n')
    .filter((l) => l.length > 0 && !l.startsWith('#'))
    .map((l) => l.replaceAll('\\n', '\n')));
}

/** meitou.ignore's two sections: the game's texts (Kenshi's catalog translates them) and texts not shown, split at the '# Not shown' line. */
function readIgnore(path) {
  const lines = existsSync(path) ? readFileSync(path, 'utf8').split('\n') : [];
  const split = lines.findIndex((l) => l.startsWith('# Not shown'));
  const entries = (part) => new Set(part.filter((l) => l.length > 0 && !l.startsWith('#')).map((l) => l.replaceAll('\\n', '\n')));
  return split < 0 ? { game: entries(lines), notShown: new Set() } : { game: entries(lines.slice(0, split)), notShown: entries(lines.slice(split)) };
}

/** Whether <text> holds a word outside its placeholders (a bare number format has nothing to translate). */
function hasWords(text) {
  return /[A-Za-z]{2,}/.test(text.replace(/\{[^{}]*\}/g, ' '));
}

/** Whether <text> reads as words a player sees, not an identifier, path, format or code. */
function isProse(text) {
  if (!hasWords(text)) return false;
  const words = text.replace(/\{[^{}]*\}/g, 'X').trim();
  if (/^[a-z]+ {2,}/.test(words)) return false;
  if (/\\|^\w+:\/\/|^#|^[a-z_]+\.[a-z_.]+$/i.test(words)) return false;
  if (!words.includes(' ') && words.includes('/')) return false;
  if (/^[\w.-]+\.(ttf|dds|png|mesh|xml|json|txt|cfg|mod|layout|mo|po|exe|dll|cs|wav|bnk|ogg|mp4)$/i.test(words)) return false;
  if (!words.includes(' ')) return /^([A-Z][a-z]+(-[a-z]+)*|[A-Z]{4,})[.!?…:]?$/.test(words);
  return words.match(/[A-Za-z]+/g).some((w) => w.length >= 3);
}

/** Whether the literal is an indexer key on its line (["Name"] = ...): a property name, not text. */
function isDictionaryKey(line, raw) {
  return line.includes(`["${raw}"]`) || line.includes(`[$"${raw}"]`);
}

/** Decodes the XML entities an axaml attribute may hold. */
function unescapeXml(s) {
  return s.replaceAll('&quot;', '"').replaceAll('&apos;', '\'').replaceAll('&lt;', '<').replaceAll('&gt;', '>').replaceAll('&amp;', '&');
}

/**
 * The string literals of C# source and the source with comments and literal text blanked (line breaks and an interpolation's holes kept):
 * lits are { value, raw, interpolated, indexer, line, start, end }, those inside interpolation holes included, literals joined by '+' merged.
 * value is the text the literal makes (escapes decoded; an interpolation's holes as written).
 */
function scan(src) {
  const masked = src.split('');
  const lits = [];
  const lineStarts = [0];
  for (let k = 0; k < src.length; k++) if (src[k] === '\n') lineStarts.push(k + 1);
  const lineOf = (pos) => {
    let lo = 0;
    let hi = lineStarts.length - 1;
    while (lo < hi) {
      const mid = (lo + hi + 1) >> 1;
      if (lineStarts[mid] <= pos) lo = mid;
      else hi = mid - 1;
    }
    return lo + 1;
  };
  const blank = (from, to) => {
    for (let k = from; k < to; k++) if (masked[k] !== '\n') masked[k] = ' ';
  };
  scanRange(src, 0, src.length, { lits, blank, lineOf });
  return { lits: lits.sort((a, b) => a.start - b.start), masked: masked.join('') };
}

/** Scans src[from, to) as code: blanks comments and literals, records literals and scans their holes as code. */
function scanRange(src, from, to, ctx) {
  let i = from;
  let previous = null;
  while (i < to) {
    const c = src[i];
    if (src.startsWith('//', i)) { const end = Math.min(skipTo(src, '\n', i), to); ctx.blank(i, end); i = end; continue; }
    if (src.startsWith('/*', i)) { const end = Math.min(src.indexOf('*/', i) + 2 || to, to); ctx.blank(i, end); i = end; continue; }
    if (c === '\'') { const end = skipChar(src, i); ctx.blank(i + 1, end - 1); i = end; continue; }

    const lit = readLiteral(src, i);
    if (!lit) { i++; continue; }
    lit.line = ctx.lineOf(i);
    lit.indexer = /\[\s*$/.test(src.slice(Math.max(from, i - 8), i)) && /^\s*\]/.test(src.slice(lit.end, lit.end + 8));
    let text = lit.start + lit.open;
    for (const [h0, h1] of lit.holes) {
      ctx.blank(text, h0);
      scanRange(src, h0, h1, ctx);
      text = h1;
    }
    ctx.blank(text, lit.end - lit.close);

    if (previous && !previous.interpolated && !lit.interpolated && /^\s*\+\s*$/.test(src.slice(previous.end, lit.start))) {
      previous.value += lit.value;
      previous.raw += lit.raw;
      previous.end = lit.end;
    } else {
      ctx.lits.push(lit);
      previous = lit;
    }
    i = lit.end;
  }
}

/** The index of the next <ch> at or after <i>, or the end of <s>. */
function skipTo(s, ch, i) {
  const at = s.indexOf(ch, i);
  return at < 0 ? s.length : at;
}

/** The index after the character literal starting at <i> (at a line break when it is not closed: an apostrophe in a #region title). */
function skipChar(s, i) {
  let j = i + 1;
  while (j < s.length && s[j] !== '\'' && s[j] !== '\n') j += s[j] === '\\' ? 2 : 1;
  return s[j] === '\'' ? j + 1 : j;
}

/**
 * The literal starting at <i> (regular, verbatim, interpolated or raw), or null when none starts there: its value and raw text, the lengths of
 * its opening and closing quotes, and the spans of its interpolation holes.
 */
function readLiteral(src, i) {
  const head = src.slice(i, i + 8).match(/^(\$+)?(@)?(\$+)?("""+|")/);
  if (!head || (i > 0 && /[\w"]/.test(src[i - 1]))) return null;

  const dollars = (head[1] ?? head[3] ?? '').length;
  const interpolated = dollars > 0;
  const verbatim = Boolean(head[2]);
  const quote = head[4];
  const start = i + head[0].length;
  if (quote.length >= 3) {
    const close = src.indexOf(quote, start);
    const raw = src.slice(start, close);
    const holes = interpolated ? rawHoles(src, start, close, dollars) : [];
    return { value: dedentRaw(raw), raw, interpolated, holes, start: i, end: close + quote.length, open: head[0].length, close: quote.length };
  }

  const holes = [];
  const close = closingQuote(src, start, verbatim, interpolated, holes);
  const raw = src.slice(start, close);
  return { value: decode(raw, verbatim), raw, interpolated, holes, start: i, end: close + 1, open: head[0].length, close: 1 };
}

/** The index of the quote that ends a one-quote literal whose text starts at <j>; an interpolation's holes are added to <holes>. */
function closingQuote(src, j, verbatim, interpolated, holes) {
  while (j < src.length) {
    const ch = src[j];
    if (verbatim && ch === '"' && src[j + 1] === '"') { j += 2; continue; }
    if (!verbatim && ch === '\\') { j += 2; continue; }
    if (interpolated && ch === '{') {
      if (src[j + 1] === '{') { j += 2; continue; }
      const end = holeEnd(src, j + 1);
      holes.push([j + 1, end]);
      j = end + 1;
      continue;
    }
    if (ch === '"' || ch === '\n') return j;
    j++;
  }
  return j;
}

/** The index of the '}' that closes an interpolation hole whose code starts at <j> (literals inside it skipped whole). */
function holeEnd(src, j) {
  let depth = 0;
  while (j < src.length) {
    const lit = readLiteral(src, j);
    if (lit) { j = lit.end; continue; }
    const ch = src[j];
    if (ch === '{' || ch === '(' || ch === '[') depth++;
    else if ((ch === ')' || ch === ']') && depth) depth--;
    else if (ch === '}') {
      if (depth === 0) return j;
      depth--;
    }
    j++;
  }
  return j;
}

/** The holes of a raw interpolated literal's text src[from, to) with <dollars> dollar signs: code between that many braces. */
function rawHoles(src, from, to, dollars) {
  const holes = [];
  const open = '{'.repeat(dollars);
  let j = from;
  while ((j = src.indexOf(open, j)) >= 0 && j < to) {
    const end = holeEnd(src, j + dollars);
    holes.push([j + dollars, end]);
    j = end + dollars;
  }
  return holes;
}

/** The text of a regular or verbatim literal's source. */
function decode(raw, verbatim) {
  if (verbatim) return raw.replaceAll('""', '"');
  return raw.replace(/\\(u[0-9a-fA-F]{4}|x[0-9a-fA-F]{1,4}|.)/g, (_, e) => {
    if (e[0] === 'u' || e[0] === 'x') return String.fromCharCode(parseInt(e.slice(1), 16));
    return { n: '\n', t: '\t', r: '\r', 0: '\0', '"': '"', '\'': '\'', '\\': '\\' }[e] ?? e;
  });
}

/** The text of a raw string literal: the lines inside the quotes, less the closing line's indentation. */
function dedentRaw(raw) {
  const lines = raw.split('\n');
  if (lines.length < 3) return raw;
  const indent = lines.at(-1).length;
  return lines.slice(1, -1).map((l) => l.slice(indent)).join('\n');
}
